SET NAMES utf8mb4;
USE shineconnoisseur;
CREATE TABLE IF NOT EXISTS `admin` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `real_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_login_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `admin` VALUES (1,'lzh','$2a$10$LT4rVX5TPZbPJkUCPG/jp.pDtzuQmTnImDCrmjEXsGBZPQZ1Rngue','卢展弘','1234567@qq.com','https://api.dicebear.com/7.x/avataaars/svg?seed=2','2024-06-23 13:10:00','2023-06-23 13:10:00','2025-06-23 13:10:00');
CREATE TABLE IF NOT EXISTS `like_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `target_id` bigint NOT NULL COMMENT '目标ID（评论ID或影评ID）',
  `target_type` tinyint NOT NULL COMMENT '类型：1评论 2影评',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_target` (`user_id`,`target_id`,`target_type`),
  KEY `idx_target` (`target_id`,`target_type`),
  KEY `idx_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='点赞记录表（评论/影评通用）';
INSERT INTO `like_record` VALUES (15,31,22,2,'2026-07-20 20:21:09','2026-07-20 20:21:09'),(19,1,22,2,'2026-07-20 23:55:53','2026-07-20 23:55:53'),(26,31,1,1,'2026-07-25 21:26:56','2026-07-25 21:26:56'),(27,31,36,2,'2026-07-25 21:27:45','2026-07-25 21:27:45'),(28,1,38,2,'2026-07-26 20:15:21','2026-07-26 20:15:21'),(30,1,36,2,'2026-07-27 17:24:19','2026-07-27 17:24:19'),(32,1,30,1,'2026-07-27 21:34:58','2026-07-27 21:34:58'),(35,31,40,2,'2026-07-28 20:58:24','2026-07-28 20:58:24'),(36,31,39,2,'2026-07-28 20:58:25','2026-07-28 20:58:25'),(37,1,40,2,'2026-07-28 20:58:31','2026-07-28 20:58:31'),(38,1,39,2,'2026-07-28 20:58:32','2026-07-28 20:58:32');
CREATE TABLE IF NOT EXISTS `message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息id',
  `user_id` bigint NOT NULL COMMENT '接收消息的用户id',
  `from_user_id` bigint NOT NULL COMMENT '触发消息的用户id',
  `type` int NOT NULL COMMENT '消息类型 0-关注 1-点赞影评 2-评论影评 3-点赞评论 4-回复评论',
  `target_type` int NOT NULL COMMENT '目标类型 0-用户 1-影评 2-评论',
  `target_id` bigint NOT NULL COMMENT '关联业务id',
  `content` varchar(255) DEFAULT NULL COMMENT '消息内容',
  `status` int NOT NULL DEFAULT '0' COMMENT '阅读状态 0-未读 1-已读',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_from_user_id` (`from_user_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_user_status` (`user_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='消息通知表';
