CREATE TABLE IF NOT EXISTS `movie` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '电影ID',
  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '电影名称',
  `original_title` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原名（外文）',
  `cover` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '海报URL',
  `director` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '导演，逗号分隔',
  `actors` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '演员，逗号分隔',
  `genre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型，逗号分隔（剧情/喜剧/科幻）',
  `region` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地区',
  `language` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '语言',
  `release_date` date DEFAULT NULL COMMENT '上映日期',
  `duration` int unsigned DEFAULT NULL COMMENT '片长（分钟）',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '剧情简介',
  `rating_sum` decimal(10,1) NOT NULL DEFAULT '0.0' COMMENT '评分总分',
  `rating_count` int unsigned NOT NULL DEFAULT '0' COMMENT '评分人数',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：0-下架，1-上架',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_title` (`title`),
  KEY `idx_genre` (`genre`(50)),
  KEY `idx_status_rating` (`status`,`rating_sum`),
  KEY `idx_release_date` (`release_date`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='电影表';
INSERT INTO `movie` VALUES (1,'肖申克的救赎','The Shawshank Redemption','uploads/images/movie/4476fca0343d45e88af2a31efc0c372d.jpg','弗兰克·德拉邦特','蒂姆·罗宾斯,摩根·弗里曼','剧情,犯罪,励志','美国','英语','1994-09-10',142,'一场谋杀案使银行家安迪蒙冤入狱，谋杀妻子及其情人的罪名将他送进了肖申克监狱。在十九年的牢狱生涯中，他用智慧和希望完成了自我救赎。',19.0,2,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(2,'霸王别姬','Farewell My Concubine','uploads/images/movie/bb6d52f7925c47d9846f676cc019c1e3.jpg','陈凯歌','张国荣,张丰毅,巩俐','剧情,爱情','中国','汉语普通话','1993-01-01',171,'段小楼与程蝶衣是一对打小一起长大的师兄弟，两人一个演生，一个饰旦，一向配合天衣无缝，尤其一出《霸王别姬》，誉满京城。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 21:04:02'),(3,'阿甘正传','Forrest Gump','uploads/images/movie/bd0fc5c0116c4be6bbcc548c6cf601d1.jpg','罗伯特·泽米吉斯','汤姆·汉克斯,罗宾·怀特','剧情,爱情,社会','美国','英语','1994-06-23',142,'阿甘是个智商只有75的低能儿，但他的人生却像一盒巧克力，你永远不知道下一颗是什么味道。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(4,'泰坦尼克号','Titanic','uploads/images/movie/357454ab00a447fb92703f9c82c67c30.jpg','詹姆斯·卡梅隆','莱昂纳多·迪卡普里奥,凯特·温丝莱特','剧情,爱情,灾难','美国','英语','1997-12-19',194,'1912年4月10日，号称\"世界工业史上的奇迹\"的豪华客轮泰坦尼克号开始了自己的处女航，从英国的南安普顿出发驶往美国纽约。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 21:11:11'),(5,'千与千寻','千と千尋の神隠し','uploads/images/movie/1c58630a2078477d9d50b46d0c06b9ea.jpg','宫崎骏','柊瑠美,入野自由','动画,奇幻,冒险','日本','日语','2001-07-20',125,'千寻和爸爸妈妈一同驱车前往新家，在郊外的小路上不慎进入了神秘的隧道，来到了一个诡异世界。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:40'),(6,'美丽人生','La vita è bella','uploads/images/movie/190768f4541742beb22e4fa573944111.jpg','罗伯托·贝尼尼','罗伯托·贝尼尼,尼可莱塔·布拉斯基','剧情,喜剧,爱情','意大利','意大利语','1997-12-20',116,'犹太青年圭多邂逅了美丽的女教师多拉，他彬彬有礼地向多拉鞠躬：\"早安！公主！\"。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:40'),(7,'星际穿越','Interstellar','uploads/images/movie/b69ba07a44234f9f805bc2c786c3aa24.jpg','克里斯托弗·诺兰','马修·麦康纳,安妮·海瑟薇','剧情,科幻,冒险','美国','英语','2014-11-07',169,'近未来的地球黄沙遍野，小麦、秋葵等基础农作物相继因枯萎病灭绝，人类不再像从前那样仰望星空，放纵想象力。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:41'),(8,'盗梦空间','Inception','uploads/images/movie/d3c4674a722546d69b63aef71f9a4371.jpg','克里斯托弗·诺兰','莱昂纳多·迪卡普里奥,约瑟夫·高登-莱维特','动作,科幻,悬疑','美国','英语','2010-09-01',148,'道姆·柯布与同事阿瑟和纳什在一次针对日本能源大亨齐藤的盗梦行动中失败，反被齐藤利用。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(9,'楚门的世界','The Truman Show','uploads/images/movie/a210a010e537489d84a4c1606dd1d280.jpg','彼得·威尔','金·凯瑞,劳拉·琳妮','剧情,科幻,喜剧','美国','英语','1998-06-05',103,'楚门是一个标准的中产阶级，他生活在桃源岛，一个风景如画的小城。但他不知道的是，他的一举一动都被全球直播。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(10,'三傻大闹宝莱坞','3 Idiots','uploads/images/movie/d694fd5311494c7a955f414cab08bd36.jpg','拉吉库马尔·希拉尼','阿米尔·汗,卡琳娜·卡普尔','剧情,喜剧,励志','印度','印地语','2009-12-25',170,'法兰、拉杜与兰乔是皇家工程学院的学生，三人共居一室，结为好友。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(11,'机器人总动员','WALL·E','uploads/images/movie/86e591211a654d428158e4f2b7086b58.jpg','安德鲁·斯坦顿','本·贝尔特,艾丽莎·奈特','科幻,动画,冒险','美国','英语','2008-06-27',98,'公元2805年，人类文明高度发展，却因污染和生活垃圾大量增加使得地球不再适于人类居住。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:40'),(12,'放牛班的春天','Les choristes','uploads/images/movie/02a787b9aa264f10b3de06e644bd54b3.jpg','克里斯托夫·巴拉蒂','让-巴蒂斯特·莫尼耶,热拉尔·朱尼奥','剧情,音乐,励志','法国','法语','2004-03-17',97,'1949年的法国乡村，音乐家克莱门特到了一间外号叫\"塘低\"的男子寄宿学校当助理教师。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(13,'大话西游之大圣娶亲','西游记大结局之仙履奇缘','uploads/images/movie/364103e0862e479aaf5feb4510ec301c.jpg','刘镇伟','周星驰,朱茵','喜剧,爱情,奇幻','中国','粤语','1995-02-04',95,'至尊宝被月光宝盒带回到五百年前，遇见紫霞仙子，被对方打上烙印成为对方的人，并发觉自己已变成孙悟空。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:40'),(14,'熔炉','도가니','uploads/images/movie/caf935d17b2a41b7aa0e85ba00f12890.jpg','黄东赫','孔刘,郑有美','剧情,社会','韩国','韩语','2011-09-22',125,'来自首尔的哑语美术老师仁浩来到雾津，应聘慈爱聋哑人学校。天降大雾，他意外撞车，维修时结识了人权组织成员柔珍。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(15,'教父','The Godfather','uploads/images/movie/be659ba6e67e4d878c6869a64105ac4c.jpg','弗朗西斯·福特·科波拉','马龙·白兰度,阿尔·帕西诺','剧情,犯罪,悬疑','美国','英语','1972-03-24',175,'40年代的美国，\"教父\"维托·唐·柯里昂是黑手党柯里昂家族的首领，带领家族从事非法的勾当。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(16,'无间道','無間道','uploads/images/movie/31b807d1ca0d4688977ab384b524ba92.jpg','刘伟强,麦兆辉','刘德华,梁朝伟,黄秋生','剧情,犯罪,悬疑','中国','粤语','2002-12-12',101,'1991年，香港黑帮三合会会员刘健明听从老大韩琛的指示，加入警察部队成为黑帮卧底。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:40'),(17,'疯狂动物城','Zootopia','uploads/images/movie/38b209e84adc4a8fb44c7455a679198a.jpg','拜伦·霍华德,瑞奇·摩尔','金妮弗·古德温,杰森·贝特曼','喜剧,动画,冒险','美国','英语','2016-03-04',109,'故事发生在一个所有哺乳类动物和谐共存的美好世界中，兔子朱迪从小就梦想着能够成为一名惩恶扬善的刑警。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:40'),(18,'当幸福来敲门','The Pursuit of Happyness','uploads/images/movie/ae5b9f9dc7394a38b9ab83b7879d7325.jpg','加布里尔·穆奇诺','威尔·史密斯,贾登·史密斯','剧情,传记,家庭','美国','英语','2006-12-15',117,'克里斯·加纳用尽全部积蓄买下了高科技治疗仪，到处向医院推销，可是价格高昂，接受的人不多。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:40'),(19,'怦然心动','Flipped','uploads/images/movie/579b4f90d4484cc2ac00e4e0925dde6c.jpg','罗伯·莱纳','玛德琳·卡罗尔,卡兰·麦克奥利菲','剧情,喜剧,爱情','美国','英语','2010-07-26',90,'布莱斯全家搬到小镇，邻家女孩朱丽前来帮忙。她对他一见钟情，心愿是获得他的吻。',0.0,0,1,'2026-06-14 18:46:55','2026-07-25 18:06:40'),(20,'触不可及','Intouchables','uploads/images/movie/238dc03ede154d3a817b1ec2029aa36e.jpg','奥利维埃·纳卡什,埃里克·托莱达诺','弗朗索瓦·克鲁塞,奥玛·希','剧情,喜剧,传记','法国','法语','2011-11-02',112,'因为一次跳伞事故，白人富翁菲利普瘫痪在床，欲招聘一名全职陪护。',0.0,0,1,'2026-06-14 18:46:55','2026-07-26 20:55:42'),(21,'辛德勒的名单','Schindler\'s List','uploads/images/movie/999a0dd33a114ef69d1d89919d91facd.png','史蒂文·斯皮尔伯格','连姆·尼森,本·金斯利,拉尔夫·费因斯','剧情,历史,战争','美国','英语','1993-11-30',195,'二战期间，德国商人奥斯卡·辛德勒来到波兰克拉科夫开设工厂，在亲眼目睹纳粹对犹太人的残酷迫害后，他倾尽家财拯救了1100多名犹太人的生命。',0.0,0,1,'2026-07-25 17:07:56','2026-07-25 18:06:40'),(22,'这个杀手不太冷','Léon','uploads/images/movie/34c0eaba9939442f9670bcb6e88ad73a.png','吕克·贝松','让·雷诺,娜塔莉·波特曼,加里·奥德曼','剧情,动作,犯罪','法国','英语','1994-09-14',110,'纽约贫民区住着一名职业杀手莱昂，一天邻居家小姑娘玛蒂尔达敲开了他的房门，她的家人被恶警杀害，她请求在莱昂这里暂避杀身之祸。',0.0,0,1,'2026-07-25 17:07:56','2026-07-25 18:06:40'),(23,'蝙蝠侠：黑暗骑士','The Dark Knight','uploads/images/movie/173d0829df48487a88b44450ddf28568.png','克里斯托弗·诺兰','克里斯蒂安·贝尔,希斯·莱杰,艾伦·艾克哈特','剧情,动作,科幻','美国','英语','2008-07-14',152,'蝙蝠侠、戈登警长和检察官哈维·丹特联手打击哥谭市的有组织犯罪，但疯狂的小丑的出现让这座城市再度陷入混乱。',0.0,0,1,'2026-07-25 17:07:56','2026-07-25 18:06:40'),(24,'十二怒汉','12 Angry Men','uploads/images/movie/55be42ce74b14f658c1b1db6d4d4a1c8.png','西德尼·吕美特','亨利·方达,李·科布,马丁·鲍尔萨姆','剧情,悬疑,法庭','美国','英语','1957-04-10',96,'一名纽约青年被控杀害自己的父亲，法庭上证据确凿，十二名不同背景的陪审团成员在一个封闭的房间内展开激烈的辩论。',0.0,0,1,'2026-07-25 17:07:56','2026-07-26 20:55:42'),(25,'搏击俱乐部','Fight Club','uploads/images/movie/1efa016347114830a165e49ea0f5d7e0.png','大卫·芬奇','布拉德·皮特,爱德华·诺顿,海伦娜·伯翰·卡特','心理,动作,悬疑','美国','英语','1999-10-15',139,'杰克是一个大汽车公司的职员，患有严重的失眠症。他遇到了肥皂商人泰勒，两人共同创建了一个不为人知的地下搏击俱乐部。',0.0,0,1,'2026-07-25 17:07:56','2026-07-26 20:55:42'),(26,'指环王1：护戒使者','The Lord of the Rings: The Fellowship of the Ring','uploads/images/movie/26c6b594ab7c48138eb75cea6c7c9312.png','彼得·杰克逊','伊利亚·伍德,伊恩·麦克莱恩,维果·莫腾森','冒险,动作,奇幻','新西兰,美国','英语','2001-12-19',179,'在古老的中土世界，黑暗魔君索伦铸造了至尊魔戒。这枚戒指辗转落到了霍比特人弗罗多·巴金斯的手中，他必须踏上毁灭魔戒的征程。',0.0,0,1,'2026-07-25 17:07:56','2026-07-26 20:55:42'),(27,'指环王2：双塔奇兵','The Lord of the Rings: The Two Towers','uploads/images/movie/7bb007e1176f42c395047c3a1a89a820.png','彼得·杰克逊','伊利亚·伍德,伊恩·麦克莱恩,维果·莫腾森','冒险,动作,奇幻','新西兰,美国','英语','2002-12-18',180,'弗罗多和山姆继续前往魔多，途中抓住了觊觎魔戒的咕噜。同时阿拉贡、莱戈拉斯和吉姆利在洛汗王国抵抗萨鲁曼的大军。',0.0,0,1,'2026-07-25 17:07:56','2026-07-26 20:55:42'),(28,'指环王3：王者无敌','The Lord of the Rings: The Return of the King','uploads/images/movie/d7e717fc729f409ca595e46bd7ce81f0.png','彼得·杰克逊','伊利亚·伍德,伊恩·麦克莱恩,维果·莫腾森','冒险,动作,奇幻','新西兰,美国','英语','2003-12-17',201,'弗罗多和山姆在咕噜的引导下来到末日火山。阿拉贡率领人类最后的力量在黑门前与索伦大军展开决战，为中土世界的命运而战。',0.0,0,1,'2026-07-25 17:07:56','2026-07-26 20:55:42'),(29,'飞越疯人院','One Flew Over the Cuckoo\'s Nest','uploads/images/movie/eb11558dbafb4060916f8a7fa844e8ab.png','米洛斯·福尔曼','杰克·尼科尔森,路易丝·弗莱彻,威尔·萨姆森','剧情,心理,喜剧','美国','英语','1975-11-19',133,'麦克墨菲为了逃避监狱里的强制劳动，装作精神异常，被送进了精神病院。他的到来给死气沉沉的精神病院带来了自由的空气。',0.0,0,1,'2026-07-25 17:07:56','2026-07-26 20:55:42'),(30,'七武士','七人の侍','uploads/images/movie/4a6213240639494a9f1e83371cb61d53.png','黑泽明','三船敏郎,志村乔,千秋实','剧情,动作,冒险','日本','日语','1954-04-26',207,'日本战国时代，一个山村经常遭受山贼的抢劫。村民们决定雇佣七名武士来保卫村庄，最终与山贼展开了一场惨烈的决战。',0.0,0,1,'2026-07-25 17:07:56','2026-07-25 18:06:40'),(31,'黑客帝国','The Matrix','uploads/images/movie/3b17e52eb45740349056d9bfecd5cf65.png','沃卓斯基姐妹'